import React from 'react';

import { DEFAULT_LABELS_WIDTH } from './constants.js';

interface AnnotationsContextProps {
  showLabels: boolean;
  labelsWidth: number;
  trackWidth: number;
  clipPathId: string;
}

export const AnnotationsContext = React.createContext<AnnotationsContextProps>({
  showLabels: true,
  labelsWidth: DEFAULT_LABELS_WIDTH,
  trackWidth: 0,
  clipPathId: 'track-limit',
});

AnnotationsContext['displayName'] = 'Annotations.Context';
